import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture (cached by ctx.textureLoader)
  const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  const texture = ctx.textureLoader.load(imageUrl);

  // Create plane geometry (16:10 aspect ratio based on atlas region 512x320)
  const geometry = new THREE.PlaneGeometry(1, 0.625);

  // Create material using Node-based shader system for WebGPU
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position, rotation, and scale
  const scenePos = config.scenePosition || {
    x: 0,
    y: 0,
    z: 0,
  };

  mesh.position.set(scenePos.x, scenePos.y, scenePos.z);

  if (scenePos.rotationXYZ) {
    mesh.rotation.set(
      scenePos.rotationXYZ[0],
      scenePos.rotationXYZ[1],
      scenePos.rotationXYZ[2]
    );
  }

  if (scenePos.scaleXYZ) {
    mesh.scale.set(
      scenePos.scaleXYZ[0],
      scenePos.scaleXYZ[1],
      scenePos.scaleXYZ[2]
    );
  }

  group.add(mesh);

  // Setup resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  // Initialize event handlers (empty for this static element)
  group.userData.handlers = {};

  return group;
}
